class ParkingLot:
    def __init__(self, capacity):
        self.capacity = capacity
        self.cars = []

    def enter(self, car):
        if len(self.cars) < self.capacity and car not in self.cars:
            self.cars.append(car)
            return True
        return False

    def leave(self, car):
        if car in self.cars:
            self.cars.remove(car)
            return True
        return False

    def count(self):
        return len(self.cars)

    def is_full(self):
        return len(self.cars) >= self.capacity

